<dialog id="confirm-dialog" class="confirm-dialog" aria-labelledby="confirm-title" aria-describedby="confirm-message"><form method="dialog"><span class="empty-icon danger"><x-icon name="shield" /></span><h2 id="confirm-title">¿Quieres continuar?</h2><p id="confirm-message"></p><div class="form-actions"><button type="submit" class="button button-secondary" value="cancel" autofocus>Volver y revisar</button><button type="submit" class="button button-danger" id="confirm-accept" value="confirm">Sí, continuar</button></div></form></dialog>
